// Some portions generated by Codex

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const vm = require('node:vm');
const { spawnSync } = require('node:child_process');
const { classicCompilerOptions } = require('./workbench-scripts.js');
const { createMemoryRowStore } = require('./explore-section-fixtures.js');

const exploreSource = path.resolve(__dirname, '../../../main/frontend/classic/explore.ts');

function loadExploreController() {
    const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'rdf4j-explore-local-pages-'));
    const output = path.join(directory, 'explore.js');
    const compilation = spawnSync('tsc', [
        ...classicCompilerOptions(),
        '--target', 'ES2017',
        '--lib', 'ES2017,DOM',
        '--skipLibCheck',
        '--outFile', output,
        exploreSource
    ], { encoding: 'utf8' });
    assert.equal(compilation.status, 0,
        `Explore source must compile for the independent section-page contract:\n${compilation.stdout}${compilation.stderr}`);

    const window = {};
    const workbench = { queryStream: {} };
    const context = vm.createContext({ AbortController, Promise, URL, URLSearchParams, clearTimeout, setTimeout,
        window, workbench });
    vm.runInContext(fs.readFileSync(output, 'utf8'), context, { filename: output });
    return context.workbench.explore;
}

function memoryStore(rows, stores) {
    const store = createMemoryRowStore(rows);
    stores.push(store);
    return store;
}

async function waitFor(predicate) {
    for (let attempt = 0; attempt < 200 && !predicate(); attempt++) {
        await new Promise(resolve => setImmediate(resolve));
    }
    assert.ok(predicate(), 'the requested section cache and count become ready');
}

test('Explore role counts stay exact while each section pages through its own cache', async () => {
    const explore = loadExploreController();
    const requests = [];
    const stores = [];
    const rows = Array.from({ length: 300 }, (_unused, index) => [
        { kind: 'iri', value: `urn:subject:${index}` },
        { kind: 'iri', value: 'urn:predicate' },
        { kind: 'literal', value: `value-${index}` },
        index % 2 ? { kind: 'iri', value: 'urn:named-graph' } : null
    ]);
    const controller = explore.createSectionController({
        url: 'https://example.test/workbench/repositories/r/explore?resource=%3Curn%3Aresource%3E&offset=200&limit_explore=0',
        repositoryScope: 'server/repository',
        fetcher: async () => ({ ok: true }),
        loadModel: async (_fetcher, rawUrl) => {
            const url = new URL(rawUrl);
            requests.push(url);
            const key = url.searchParams.get('section');
            const kind = url.searchParams.get('kind');
            if (kind === 'count') {
                const count = key === 'outgoing'
                    ? url.searchParams.get('scope') === 'default' ? '125' : '175'
                    : '0';
                return { rowCount: 0, metadata: { 'explore-count': count } };
            }
            const sectionRows = key === 'outgoing' ? rows : [];
            return {
                rowStore: memoryStore(sectionRows, stores),
                rowCount: sectionRows.length,
                vars: ['subject', 'predicate', 'object', 'context'],
                metadata: {}
            };
        }
    });
    controller.start();
    await waitFor(() => controller.sections.outgoing.status === 'ready'
        && controller.sections.outgoing.countStatus === 'ready');

    const outgoing = controller.sections.outgoing;
    assert.equal(outgoing.count, '300', 'the exact server count combines default and named graphs');
    assert.equal(outgoing.totalRows, 300, 'the section cache has all currently available statement rows');
    assert.equal(outgoing.rows.length, 100, 'role sections expose a 100-row local page');
    assert.equal(outgoing.rows[0][0].value, 'urn:subject:0');
    assert.equal(outgoing.start, 0, 'legacy URL offsets do not select a server page');

    const rowRequests = requests.filter(url => url.searchParams.get('section') === 'outgoing'
        && url.searchParams.get('kind') === 'rows');
    await controller.page('outgoing', 'next');
    assert.equal(outgoing.start, 100);
    assert.equal(outgoing.rows[0][0].value, 'urn:subject:100');
    await controller.page('outgoing', 'next');
    assert.equal(outgoing.start, 200);
    assert.equal(outgoing.rows[0][0].value, 'urn:subject:200');
    await controller.page('outgoing', 'previous');
    assert.equal(outgoing.start, 100);
    assert.equal(outgoing.rows[0][0].value, 'urn:subject:100');
    assert.equal(requests.filter(url => url.searchParams.get('section') === 'outgoing'
        && url.searchParams.get('kind') === 'rows').length, rowRequests.length,
        'local page movement reads the section cache without another server request');
    assert.ok(requests.every(url => !url.searchParams.has('offset') && !url.searchParams.has('limit_explore')),
        'section requests never inherit legacy server paging parameters');

    controller.dispose();
    await waitFor(() => stores.every(store => store.disposed));
});
